roduct-gallery__zoom:focus-visible .product-gallery__zoom-label{opacity:1}.product-gallery__video,.product-gallery__item model-viewer,.product-gallery__item>svg{display:block;width:100%;height:100%;min-height:0;object-fit:contain}.product-gallery__controls:not([hidden]){display:flex;align-items:center;justify-content:space-between;padding:8px 18px;background:#fff;font-size:9px;letter-spacing:1px;border-top:1px solid #f1f0ee}.product-gallery__controls button{border:0;background:none;cursor:pointer;width:44px;height:44px;font-size:18px;color:inherit}.product-gallery__controls button:disabled{opacity:.3;cursor:default}.product-lightbox{width:100vw;height:100svh;max-width:100vw;max-height:100svh;inset:0;padding:0;border:0;margin:0;background:#fff}.product-lightbox::backdrop{background:#fff}.product-lightbox[open]{display:flex;align-items:center;justify-content:center}.product-lightbox img{width:100%;height:100%;object-fit:contain}.product-lightbox__close{position:fixed;right:20px;top:15px;font-size:34px;width:44px;height:44px;background:#ffffffdf;border:1px solid var(--color-line);cursor:pointer;z-index:1}.product-sticky{display:none}.product-grid{display:grid;grid-template-columns:repeat(var(--desktop-columns,4),minmax(0,1fr));gap:42px 14px}.product-card{min-width:0}.product-card__media{display:block;position:relative;background:#fff;overflow:hidden}.product-card__media>img,.product-card__placeholder{display:block;width:100%;aspect-ratio:4/5;height:auto;object-fit:contain;transition:transform .65s cubic-bezier(.2,.7,.2,1)}.product-card__media:hover>img{transform:scale(1.025)}.product-card__badge{position:absolute;top:15px;left:15px;font-size:8px}.product-card__info{text-align:left;padding:12px 0 0}.product-card__heading{display:flex;align-items:baseline;justify-content:space-between;gap:12px}.product-card h3{flex:1;min-width:0;font-family:var(--font-serif);font-size:16px;font-weight:400;line-height:1.25;margin:0}.product-card h3 a{text-decoration:none}.product-card__price{flex-shrink:0;font-size:12px;margin:0;line-height:1.5;text-align:right}.product-card__price--availability{flex-shrink:1;max-width:45%;font-size:10px}.product-card__swatches{display:flex;align-items:center;justify-content:flex-start;gap:7px;flex-wrap:wrap;margin:11px 0 0;min-height:24px}.product-card__swatches a{display:block;width:26px;height:29px;border:1px solid #e7e5e1}.product-card__swatches img{width:100%;height:100%;object-fit:contain}.product-card__swatches a:hover,.product-card__swatches a:focus-visible{border-color:var(--color-text)}.product-card__swatches .product-card__more{font-size:9px;display:flex;align-items:center;justify-content:center;text-decoration:none;border:0}.collection-page,.search-page{padding-top:65px;padding-bottom:90px}.collection-page{padding-top:95px}.collection-page .collection-heading{margin-bottom:35px}.collection-heading{text-align:center;margin:0 auto 58px;max-width:720px}.collection-heading>.eyebrow{margin:0 0 18px}.collection-heading h1,.collection-heading h2{font:400 32px/1.15 var(--font-serif);margin:0 0 18px}.collection-heading .rte{font-size:12px;line-height:1.8;max-width:540px;margin:0 auto}.collection-toolbar{display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--color-line);padding:17px 0;margin:0 0 25px}.collection-toolbar .eyebrow{margin:0}.collection-filters{display:flex;align-items:center;gap:25px}.collection-filter{position:relative}.collection-filter summary{cursor:pointer;list-style:none;display:flex;gap:12px;font-size:9px}.collection-filter summary::-webkit-details-marker{display:none}.collection-filter__panel{position:absolute;top:calc(100% + 17px);left:0;z-index:5;width:280px;background:var(--color-bg);border:1px solid var(--color-line);padding:23px;box-shadow:0 6px 20px #0000000a}.collection-filter__value{font-size:11px;display:flex;align-items:center;gap:8px;padding:7px 0;line-height:1.4}.collection-filter__value>span:last-child{margin-left:auto}.collection-filter__value input{accent-color:var(--color-text)}.collection-filter__actions{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-top:20px;font-size:10px}.collection-filter__actions .button{font-size:9px;padding:12px 24px;min-height:38px}.collection-price-filter{display:flex;gap:12px}.collection-price-filter label{font-size:10px;flex:1;min-width:0}.collection-price-filter input{width:100%;border:1px solid var(--color-line);padding:10px;margin-top:8px;background:none}.collection-sort{display:flex;gap:24px;align-items:center}.collection-sort select{border:0;border-radius:0;font:inherit;font-size:10px;line-height:1.5;color:inherit;background:transparent;max-width:200px;padding:6px 0}.collection-count{font-size:9px}.collection-active-filters{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:22px}.collection-active-filters:empty{display:none}.collection-active-filters a{font-size:10px;display:flex;align-items:center;gap:14px;padding:9px 12px;border:1px solid var(--color-line);text-decoration:none}.commerce-empty{grid-column:1/-1;text-align:center;min-height:300px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:25px;font-size:13px}.commerce-pagination{display:flex;gap:14px;justify-content:center;margin-top:60px;font-size:11px}.commerce-pagination>span{display:block;padding:8px}.commerce-pagination .current{border-bottom:1px solid}.commerce-pagination a{text-decoration:none}.commerce-search-form{display:flex;border-bottom:1px solid var(--color-text);margin:40px auto 0;max-width:500px}.commerce-search-form input{flex:1;width:0;border:0;border-radius:0;padding:15px 0;background:none;font:inherit;font-size:12px}.commerce-search-form button{border:0;background:none;cursor:pointer;font-size:9px;padding:15px}.search-count{margin-bottom:35px;font-size:10px}.search-content-card{padding:25px;background:#f7f6f3}.search-content-card img{width:100%;height:auto;margin-bottom:20px}.search-content-card h2{font:400 28px/1.15 var(--