0,1fr));gap:30px 10px}.product-card__info{padding-top:12px}.product-card h3{font-size:16px}.product-card__price{font-size:11px}.product-card__price--availability{font-size:9px}.cart-form{grid-template-columns:1fr;gap:35px}.cart-summary{position:static}.product-recommendations{padding-top:55px;padding-bottom:55px}.product-lightbox__close{right:15px;top:15px}}
@media(max-width:479px){.product-card__info{padding-left:1px;padding-right:1px}.product-card__heading{gap:12px}.product-card h3{font-size:15px}.product-card__swatches{gap:4px;margin-top:10px}.product-card__swatches a{width:22px;height:25px}.collection-count{display:none}.collection-filters{gap:12px}.collection-filter__panel{position:fixed;top:auto;bottom:0;left:0;right:0;width:100%;max-height:75svh;overflow:auto;border-bottom:0;padding:24px}.cart-line{grid-template-columns:86px 1fr;gap:14px}.cart-line__total{grid-column:2;margin-top:-8px}.cart-line__details h2{font-size:23px}}
